import { createFileRoute } from "@tanstack/react-router";
/**
 * Proxy público e cacheável para as capas do catálogo `/servicos`.
 *
 * URL: /api/public/catalog-image/<file>
 *
 * CANÔNICO 0WEB (18/09/2026): as 12 capas institucionais abaixo ficam
 * versionadas dentro desta rota para que o vínculo visual não dependa do
 * bucket privado nem possa desaparecer por perda de referência no CMS.
 * Não remover uma chave sem antes substituir o vínculo correspondente em
 * `RECOVERED_COVERS` de `src/lib/services-public.functions.ts`.
 *
 * Demais arquivos continuam sendo lidos do bucket privado `service-images`.
 */
const BUNDLED_COVERS: Record<string, string> = {
  "cartao-digital.jpg": "",
  "catalogo-digital.jpg": "",
  "comunicacao-visual.jpg": "",
  "consultoria-estrategica.jpg": "",
  "ebook-profissional.jpg": "",
  "identidade-visual.jpg": "",
  "marketplace-de-servicos.jpg": "",
  "outdoor-digital.jpg": "",
  "portfolio-empresarial.jpg": "",
  "presenca-digital.jpg": "",
  "programa-de-parceiros.jpg": "",
  "videos-empresariais.jpg": "",
};

const FILE_RE = /^[a-z0-9][a-z0-9._-]{0,120}\.(webp|jpg|jpeg|png|avif)$/i;

const MIME: Record<string, string> = {
  webp: "image/webp",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  png: "image/png",
  avif: "image/avif",
};

function decodeBase64(value: string): Uint8Array {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

function imageResponse(bytes: Uint8Array, file: string, contentType: string, request: Request, source: "bundled" | "storage") {
  const etag = `W/"${bytes.byteLength.toString(36)}-${source}-${file}"`;
  if (request.headers.get("if-none-match") === etag) {
    return new Response(null, {
      status: 304,
      headers: { ETag: etag, "Cache-Control": "public, max-age=31536000, immutable" },
    });
  }
  return new Response(bytes, {
    status: 200,
    headers: {
      "Content-Type": contentType,
      "Content-Length": String(bytes.byteLength),
      "Cache-Control": "public, max-age=31536000, immutable",
      ETag: etag,
      "X-Content-Type-Options": "nosniff",
      "Access-Control-Allow-Origin": "*",
    },
  });
}

export const Route = createFileRoute("/api/public/catalog-image/$file")({
  server: {
    handlers: {
      GET: async ({ params, request }) => {
        const file = String(params.file || "");
        if (!FILE_RE.test(file)) return new Response("Not found", { status: 404 });

        const ext = file.split(".").pop()!.toLowerCase();
        const contentType = MIME[ext] ?? "application/octet-stream";
        const bundled = BUNDLED_COVERS[file];
        if (bundled) {
          return imageResponse(decodeBase64(bundled), file, contentType, request, "bundled");
        }

        try {
          const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
          const { data, error } = await supabaseAdmin.storage
            .from("service-images")
            .download(`catalog/${file}`);
          if (error || !data) return new Response("Not found", { status: 404 });
          const bytes = new Uint8Array(await data.arrayBuffer());
          return imageResponse(bytes, file, contentType, request, "storage");
        } catch {
          return new Response("Internal error", { status: 500 });
        }
      },
    },
  },
});